<template>
  <div class="page-shell"><div class="page-heading"><div><h1>个人中心</h1><p>维护个人资料和登录密码。</p></div></div><div class="profile-grid"><section class="panel identity"><div class="big-avatar">{{auth.user?.realName?.slice(-1)}}</div><h2>{{auth.user?.realName}}</h2><el-tag>{{roleText[auth.role]}}</el-tag><div class="identity-code mono">UID / {{String(auth.user?.id||0).padStart(6,'0')}}</div><el-descriptions :column="1" border><el-descriptions-item label="登录账号">{{auth.user?.username}}</el-descriptions-item><el-descriptions-item label="手机号">{{auth.user?.phone||'未填写'}}</el-descriptions-item><el-descriptions-item v-if="auth.user?.policeNo" label="警号">{{auth.user.policeNo}}</el-descriptions-item><el-descriptions-item label="账号状态">正常使用</el-descriptions-item></el-descriptions></section><section class="panel forms"><el-tabs><el-tab-pane label="基本资料"><el-form :model="profile" label-width="90px"><el-form-item label="真实姓名"><el-input v-model="profile.realName"/></el-form-item><el-form-item label="手机号"><el-input v-model="profile.phone"/></el-form-item><el-form-item label="身份证号"><el-input v-model="profile.idCard"/></el-form-item><el-form-item><el-button type="primary" @click="saveProfile">保存资料</el-button></el-form-item></el-form></el-tab-pane><el-tab-pane label="修改密码"><el-form :model="password" label-width="90px"><el-form-item label="原密码"><el-input v-model="password.oldPassword" type="password" show-password/></el-form-item><el-form-item label="新密码"><el-input v-model="password.newPassword" type="password" show-password/></el-form-item><el-form-item><el-button type="primary" @click="savePassword">修改密码</el-button></el-form-item></el-form></el-tab-pane></el-tabs></section></div></div>
</template>
<script setup>
import{onMounted,reactive}from'vue';import{ElMessage}from'element-plus';import http from'../api/http';import{useAuthStore}from'../stores/auth';const auth=useAuthStore(),roleText={ADMIN:'系统管理员',POLICE:'社区民警',OWNER:'房东',TENANT:'承租人'},profile=reactive({realName:'',phone:'',idCard:''}),password=reactive({oldPassword:'',newPassword:''});onMounted(async()=>{await auth.loadMe();Object.assign(profile,auth.user)});async function saveProfile(){await http.put('/auth/profile',profile);await auth.loadMe();ElMessage.success('个人资料已保存')}async function savePassword(){if(password.newPassword.length<6){ElMessage.warning('新密码至少6位');return}await http.put('/auth/password',password);password.oldPassword='';password.newPassword='';ElMessage.success('密码修改成功')}
</script>
<style scoped>.profile-grid{display:grid;grid-template-columns:300px 1fr;gap:16px}.identity{padding:28px;text-align:center}.big-avatar{width:78px;height:78px;border-radius:20px;background:#173c57;color:#fff;display:grid;place-items:center;margin:0 auto;font-size:30px;font-weight:700}.identity h2{font-size:20px;margin:15px 0 8px}.identity-code{font-size:10px;letter-spacing:.15em;color:#91a3ac;margin:18px 0}.forms{padding:18px 25px}.forms .el-form{max-width:540px;padding-top:18px}@media(max-width:760px){.profile-grid{grid-template-columns:1fr}}</style>
